package edu.upc.dtak.aran.operators.queryengine.harness;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;
import java.util.stream.Collectors;

/**
 * Synthetic Parquet at scale, generated by DuckDB from {@code range(N)}.
 *
 * <h2>Why generate rather than commit</h2>
 *
 * <p>Every executed fixture in this repo is one to four rows, and the 100/1&nbsp;000/10&nbsp;000
 * figures in the plan tests are <em>declared</em> {@code rowCount} values that steer the cost
 * model and correspond to no data. Measuring anything needs real rows, and real rows at these
 * sizes cannot be committed.
 *
 * <h2>Why every cell is a closed form of the row index</h2>
 *
 * <p>Two reasons, and the second is the one that matters.
 *
 * <p>Reproducibility: no seed, no RNG, identical bytes on any machine and any engine.
 * Deliberately <b>not</b> DuckDB's {@code hash()} or {@code random()} — {@code random()} is not
 * reproducible at all, and {@code hash()}'s output is not contracted stable across DuckDB
 * versions, so a golden minted against one engine could move on a bump. {@code (i * 7919) % k}
 * is a permutation of {@code 0..k-1} whenever {@code gcd(7919, k) = 1}, which scatters values
 * without needing either.
 *
 * <p>And, more importantly: because the shape is a closed form, this class can state the column's
 * <em>exact</em> distinct-value count, null fraction and TRY_CAST survivor count. That is what
 * lets {@link PerfCatalogs} hand the planner statistics that are true of the data rather than
 * invented — without which a "the optimizer flips at scale" golden pins a decision made on a lie.
 *
 * <h2>Where it runs</h2>
 *
 * <p>On its own {@code jdbc:duckdb:} connection, never through {@code DuckDbExecutor}: the
 * executor's {@code prepare()} would try to build catalog views it has no catalog for, and
 * {@code restrictFilesystemTo} would have to allow the write target. Same idiom as
 * {@code SnapshotCacheTest} and {@code QueryEngineOperatorBehaviourTest.writeParquet}.
 */
final class PerfData {

    private PerfData() {}

    /** A multiplier coprime with every {@code param} used here, so {@code (i * SCATTER) % param} permutes. */
    private static final long SCATTER = 7919L;

    /**
     * How one column's cells are derived from the row index {@code i}.
     *
     * <p>{@code param} means something different per shape; each constant says what.
     */
    enum Shape {
        /** {@code '<prefix>' || i} — distinct in every row. param unused. */
        UNIQUE_KEY,
        /** {@code '<prefix>' || (i % param)} — a foreign key into a param-row parent. */
        FK,
        /** {@code 'g' || ((i * 7919) % param)} — param distinct values, scattered not clustered. */
        GROUP_KEY,
        /** {@code i % param} — a BIGINT measure with param distinct values. */
        MEASURE_INT,
        /** {@code i / 7.0} — a DOUBLE measure, distinct in every row. param unused. */
        MEASURE_DOUBLE,
        /** {@code 'v' || i} — free text, distinct in every row. param unused. */
        TEXT,
        /** {@code NULL} when {@code i % param = 0}, else {@code 't' || i}. */
        NULLABLE_TEXT,
        /** VARCHAR holding {@code 'not-a-number'} when {@code i % param = 0}, else {@code i}. */
        DIRTY_INT_TEXT
    }

    /**
     * @param literalPrefix the string {@link Shape#UNIQUE_KEY} and {@link Shape#FK} build their
     *                      values from. It exists so a key can be made unique across a class's
     *                      sources, not merely within one: two sources emitting {@code 'k' || i}
     *                      over the same range give the integrated class a key that repeats once
     *                      per source, which turns every many-to-one join into a fan-out. Making
     *                      the prefix a knob lets a workload choose which of those two shapes it
     *                      is measuring instead of getting one by accident.
     */
    record Column(String physicalName, Shape shape, long param, String literalPrefix) {
        Column(String physicalName, Shape shape, long param) {
            this(physicalName, shape, param, "k");
        }
    }

    /** One generated snapshot. {@code datasetId} doubles as the {@code SnapshotResolver} key. */
    record Spec(String datasetId, long rows, List<Column> columns) {}

    // ── Exact statistics, derived rather than measured ────────────────────────────────
    //
    // These are the whole point of the closed forms above: the catalog can declare what is
    // true instead of what someone typed.

    /** Distinct non-null values of {@code c} over {@code rows} rows. */
    static long ndv(Column c, long rows) {
        if (rows <= 0) {
            return 0L;
        }
        return switch (c.shape()) {
            case UNIQUE_KEY, MEASURE_DOUBLE, TEXT -> rows;
            case FK, GROUP_KEY, MEASURE_INT -> Math.min(c.param(), rows);
            // The null rows contribute no distinct value; the rest are distinct per row.
            case NULLABLE_TEXT -> rows - nullCount(c, rows);
            // 'not-a-number' is one distinct value, the rest are distinct per row.
            case DIRTY_INT_TEXT -> {
                long dirty = nullCount(c, rows);
                yield rows - dirty + (dirty > 0 ? 1 : 0);
            }
        };
    }

    /** Rows whose cell is NULL (or, for {@link Shape#DIRTY_INT_TEXT}, the uncastable text). */
    static long nullCount(Column c, long rows) {
        if (rows <= 0 || c.param() <= 0) {
            return 0L;
        }
        return switch (c.shape()) {
            // i in [0, rows), so the multiples of param are 0, param, 2*param, … → ceil(rows/param).
            case NULLABLE_TEXT, DIRTY_INT_TEXT -> (rows + c.param() - 1) / c.param();
            default -> 0L;
        };
    }

    /** Fraction of rows whose cell is NULL — {@code ColumnProfile.incompleteness}. */
    static double nullFraction(Column c, long rows) {
        return rows <= 0 ? 0.0 : (double) nullCount(c, rows) / rows;
    }

    /** {@code ColumnProfile.uniqueness} — NDV over row count, the ratio {@code WrapperStatistic} keys off. */
    static double uniqueness(Column c, long rows) {
        return rows <= 0 ? 0.0 : (double) ndv(c, rows) / rows;
    }

    /**
     * Rows of a {@link Shape#DIRTY_INT_TEXT} column that survive {@code TRY_CAST(... AS BIGINT)}.
     * The dirty cells are exactly the ones that do not, which is what makes the degradation
     * assertable at scale rather than by eye on three rows.
     */
    static long castableRows(Column c, long rows) {
        return rows - nullCount(c, rows);
    }

    // ── Generation ────────────────────────────────────────────────────────────────────

    /** The per-column SELECT expression. Every branch is a pure function of {@code i}. */
    private static String expression(Column c) {
        String i = "i";
        return switch (c.shape()) {
            case UNIQUE_KEY     -> "'" + c.literalPrefix() + "' || " + i;
            case FK             -> "'" + c.literalPrefix() + "' || (" + i + " % " + c.param() + ")";
            case GROUP_KEY      -> "'g' || ((" + i + " * " + SCATTER + ") % " + c.param() + ")";
            case MEASURE_INT    -> "(" + i + " % " + c.param() + ")";
            case MEASURE_DOUBLE -> "(" + i + " / 7.0)";
            case TEXT           -> "'v' || " + i;
            case NULLABLE_TEXT  -> "CASE WHEN " + i + " % " + c.param() + " = 0 THEN NULL ELSE 't' || " + i + " END";
            case DIRTY_INT_TEXT -> "CASE WHEN " + i + " % " + c.param()
                                   + " = 0 THEN 'not-a-number' ELSE CAST(" + i + " AS VARCHAR) END";
        };
    }

    /**
     * The generator statement, verbatim. Recorded in the benchmark report and hashed into the
     * cache filename, so a shape change can never read a stale file.
     */
    static String generatorSql(Spec spec) {
        String projection = spec.columns().stream()
                .map(c -> expression(c) + " AS \"" + c.physicalName().replace("\"", "\"\"") + "\"")
                .collect(Collectors.joining(", "));
        return "SELECT " + projection + " FROM range(" + spec.rows() + ") t(i)";
    }

    /** {@code build/perf/data} — under {@code build/}, so {@code .gitignore} and {@code make clean} both cover it. */
    static Path root() {
        return Path.of("build", "perf", "data");
    }

    private static final Map<String, ReentrantLock> LOCKS = new ConcurrentHashMap<>();

    /**
     * The Parquet file for {@code spec}, generated on first request and reused afterwards.
     *
     * <p>Fill discipline is {@code SnapshotCache}'s, deliberately: a per-key lock, a
     * {@code .part} file, and an atomic publish. Tests in this module run in one JVM but
     * {@link PerfRun#concurrently} starts real threads, and a half-written Parquet is a far
     * more confusing failure than a slow one.
     */
    static Path parquetFor(Spec spec) throws Exception {
        String sql = generatorSql(spec);
        String key = spec.datasetId() + "-r" + spec.rows() + "-" + shortHash(sql);
        Path target = root().resolve(key + ".parquet");
        if (Files.exists(target)) {
            return target;
        }
        ReentrantLock lock = LOCKS.computeIfAbsent(key, k -> new ReentrantLock());
        lock.lock();
        try {
            if (Files.exists(target)) {
                return target;
            }
            Files.createDirectories(root());
            Path part = root().resolve(key + ".part");
            try (Connection conn = DriverManager.getConnection("jdbc:duckdb:");
                 Statement st = conn.createStatement()) {
                st.execute("COPY (" + sql + ") TO '" + part.toAbsolutePath()
                        + "' (FORMAT PARQUET)");
            }
            Files.move(part, target, StandardCopyOption.ATOMIC_MOVE,
                    StandardCopyOption.REPLACE_EXISTING);
            return target;
        } finally {
            lock.unlock();
        }
    }

    /** The DuckDB read expression a {@code SnapshotResolver} hands back for {@code spec}. */
    static String readExpression(Path parquet) {
        return "read_parquet('" + parquet.toAbsolutePath() + "')";
    }

    private static String shortHash(String s) throws Exception {
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));
        return HexFormat.of().formatHex(digest).substring(0, 12);
    }
}
